        let mut a = vec![vec![1., 0.], vec![0., 1.], vec![1., 1.]];
        let mut b = vec![1., 2., 4.];
        let x = householder_solve(&mut a, &mut b).unwrap();
        assert!((x[0] - 4. / 3.).abs() < 1e-12);
