    let src = parse(source)?;
    let fit = parse(upstream)?;
    if src.ops != fit.ops {
        return Ok(unchanged());
    }
    if src.loops.len() != 1 || fit.loops.len() != 1 {
        return Ok(unchanged());
    }
    if src.has_curves || fit.has_curves {
        return Ok(unchanged());
    }
    if src.points.len() > MAX_VERTS {
        return Ok(unchanged());
    }
    match proper_crossings(&src.loops, &src.points) {
        Some(0) => {}
        _ => return Ok(unchanged()),
