    let edges = straight_edges(&base);
    if edges.iter().any(|e| e.len <= 0.0) {
        return Ok(unchanged());
    }
    let mut work = 0u64;
    let pairs = recognize(&base, &edges, &loops, &mut work);
    if pairs.ambiguous {
