            lower.pop();
        }
        lower.push(p.clone());
    }
    let mut upper: Vec<Rat> = Vec::new();
    for p in pts.iter().rev() {
        while upper.len() >= 2
            && cross_sign(&upper[upper.len() - 2], &upper[upper.len() - 1], p) <= 0
        {
            upper.pop();
        }
        upper.push(p.clone());
    }
    lower.pop();
    upper.pop();
    lower.extend(upper);
    lower
}

