pub(super) fn poly_edges(poly: &[Rat]) -> Vec<(Rat, Rat)> {
    if poly.len() < 2 {
        return Vec::new();
    }
    (0..poly.len())
        .map(|i| (poly[i].clone(), poly[(i + 1) % poly.len()].clone()))
        .collect()
