        let left = convex_hull(&rpts(&[[0.0, 0.0], [1.0, 0.0], [2.0, 1.0]]));
        let right = convex_hull(&rpts(&[[2.0, 1.0], [3.0, 2.0], [4.0, 2.0]]));
        let shared = lift(&[2.0, 1.0]).unwrap();
        assert!(hulls_meet_only_at(&left, &right, &shared));
    }

