    fn certify_opt_matches_oracle_degenerate() {
        // Zero-length line plus a zero-length (single-point) quad piece.
        let degenerate = vec![
            FittedCommand::MoveTo(0.0, 0.0),
            FittedCommand::LineTo(0.0, 0.0),
            FittedCommand::LineTo(4.0, 0.0),
