            FittedCommand::LineTo(x + 4.0, y),
            FittedCommand::QuadTo(x + 5.0, y + 1.0, x + 4.0, y + 2.0),
            FittedCommand::LineTo(x, y + 4.0),
            FittedCommand::Close,
