mod moving_substitution_tests {
    use super::super::geometry;
    use super::*;

    fn outline(control_x: f32) -> Vec<FittedCommand> {
        vec![
            FittedCommand::MoveTo(0.0, 0.0),
            FittedCommand::LineTo(4.0, 0.0),
            FittedCommand::QuadTo(control_x, 2.0, 4.0, 4.0),
