/// Real-outline segment reference with global control indices.
#[derive(Clone, Copy, Debug)]
pub(super) enum SegRef {
    Line { a: usize, b: usize },
    Quad { off: usize, a: usize, b: usize },
}

impl SegRef {
    fn start(self) -> usize {
        match self {
            SegRef::Line { a, .. } => a,
            SegRef::Quad { a, .. } => a,
        }
    }
}

