/// Assembled joint row with its occurrence.
struct JointRow {
    occ_prev: SegRef,
    occ_seg: SegRef,
    joint: usize,
    smooth: bool,
}

struct PairWork {
    error: Vec<f64>,
    tangent: [f64; 2],
    width: f64,
    err_gap: f64,
}

struct SolveCtx {
    rows: Vec<(RowKind, Vec<f64>, f64)>,
    pair_work: Vec<(PairWork, CurvePair)>,
    joint_rows: Vec<JointRow>,

item.aggregated_output:
    let mut degenerate: Vec<[usize; 3]> = Vec::new();
    for (j, occs) in map {
