        &parsed, &up_global, &pairs, reference, size_px, &owned, &frozen, hard,
    ) {
        Ok(c) => c,
        Err(reason) => {
            return Ok(abstain(
                preferred,
                &reason,
                serde_json::json!({ "size_px": size_px, "recognition": recognition }),
            ));
        }
    };
    let _ = fitted;
    let (mat, rhs, kinds) = restricted_matrix(&ctx, &weld);
    let ncols = ctx.cols.len();
