        assert!(diag_inf["candidates"].as_u64().unwrap() >= diag_a["candidates"].as_u64().unwrap());
        // The cap only skips key pairs, so the unbounded run keeps every
        // finite-cap pair.
        assert!(pairs_inf.len() >= pairs_a.len());
