        // Repeated control point: zero-length first leg.
        let pinned = [[0.0, 0.0], [0.0, 0.0], [2.0, 1.0]];
        check_hulls_equiv(pinned, far, None);
        check_hulls_equiv(pinned, flat, None);
    }

