    fn hull_cache_matches_oracle_separated_touching_overlapping() {
        let base = [[0.0, 0.0], [1.0, 2.0], [2.0, 0.0]];
        let far = [[10.0, 10.0], [11.0, 12.0], [12.0, 10.0]];
        check_hulls_equiv(base, far, None);
