    fn uncertain_ray_abstains() {
        let loops = vec![vec![[0.0, 0.0], [10.0, 0.0], [10.0, 10.0], [0.0, 10.0]]];
        let flats = vec![(vec![[4.0, 4.0], [6.0, 6.0]], (4.0, -100.0, 6.0, 100.0))];
        assert_eq!(certified_winding([5.0, 5.0], &loops, &flats), None);
