fn render_source_width(
    session: &CaptureSession<'_>,
    request: &ReferenceRequest,
    rasterization: crate::renderer::Rasterization,
) -> Result<ReferenceReport, Error> {
    if request.profile != PROFILE_MONO_1BIT
        || request.settings.output_bits != 1
        || rasterization != crate::renderer::Rasterization::FreeTypeMono
    {
        return Err(fail(
            "source-relative fitting requires monochrome scan conversion",
        ));
    }
    let mut upstream_request = request.clone();
    upstream_request.extensions = EXTENSIONS_FONT_HINTS_FIRST.into();
    let mut report = render_with_rasterization_in_session(
        session,
        &upstream_request,
        crate::renderer::Rasterization::FreeTypeMono,
    )?;
    report.extensions = EXTENSIONS_SOURCE_WIDTH_01.into();
    report.implementation.push_str(":source-width-01");
    if !report
        .records
        .iter()
        .any(|record| record.selected_engine == "auto")
    {
        return Ok(report);
    }
    let mut source_request = request.clone();
    source_request.extensions = "none".into();
    source_request.settings.hinting = Hinting::None;
    source_request.settings.mono_raster = Default::default();
    let source = session.source(&source_request)?;
    if source.records.len() != report.records.len() {
        return Err(fail("width source repertoire changed"));
    }
    for (record, raw) in report.records.iter_mut().zip(&source.records) {
        if record.codepoint != raw.codepoint || record.glyph_id != raw.glyph_id {
            return Err(fail("width source glyph identity changed"));
        }
        if record.selected_engine != "auto" {
            continue;
        }
        // Width recognition is optional after a successful upstream scan.
        // Unsupported source-domain geometry must keep that glyph usable.
        let Ok(fit) = crate::source_width::fit(
            &raw.fitted_commands,
            &record.fitted_commands,
            request.settings.size_px,
        ) else {
            continue;
        };
        if !fit.applied {
            continue;
        }
        // Hobby (5)/(17) adjusts recognized widths before the shared scanner;
        // scaler-returned advances and source layout stay with the upstream fit.
        let Ok(raster) = crate::mono::rasterize(&fit.commands, &request.settings) else {
            continue;
        };
        record.width_fitting = Some(crate::reference::SourceWidthCapture {
            size_px: request.settings.size_px,
            upstream_commands: record.fitted_commands.clone(),
        });
    if report.records.len() != source.records.len() {
        return Err(fail("terminal source repertoire changed"));
    }
    for (record, raw) in report.records.iter_mut().zip(&source.records) {
        if record.codepoint != raw.codepoint || record.glyph_id != raw.glyph_id {
            return Err(fail("terminal source glyph identity changed"));
        }
        // Executed font scan state remains authoritative. The automatic
        // path suppresses only source/fitted supporting-cap rescues;
        // SCANTYPE 5 globally would also remove interior junction pixels.
        if record.selected_engine != "auto" {
            continue;
        }
        let output = rasterize_terminals(
            &raw.fitted_commands,
            &record.fitted_commands,
            &request.settings,
        )?;
        record.pixels = output.pixels;
        record.raster_policy = crate::reference::RasterPolicy::FreeTypeMonoTerminals;
        record.source_commands = Some(raw.fitted_commands.clone());
    }
    report.implementation.push_str(":source-terminals-01");
    Ok(report)
}

pub(crate) fn rasterize_terminals(
    source: &[crate::probe::FittedCommand],
    fitted: &[crate::probe::FittedCommand],
    config: &Config,
) -> Result<crate::probe::RasterOutput, Error> {
    let mut output = crate::mono::rasterize(fitted, config)?;
    let mut no_stubs = config.clone();
    no_stubs.mono_raster.include_stubs = false;
    no_stubs.mono_raster.font_instructions = false;
    let without = crate::mono::rasterize(fitted, &no_stubs)?;
    output.pixels =
        crate::terminal_caps::suppress_certified(source, fitted, &output, &without)?.pixels;
    Ok(output)
}

/// Generate the working candidate as a bitmap strike.
///
/// This is the maintained candidate counterpart to legacy `generate()`:
/// glyph bitmaps and offsets come from the candidate capture, advances are
/// whole pixels (fitted when available, otherwise the rounded source
//! Composition of the reviewed fitting models with original-input authority.
//!
//! Each feature solve owns its geometry; unsupported features retain the
//! preceding delivery. The terminal stage addresses source-cap violations,
//! rather than replacing an already constrained crossing or curve result.

use super::{geometry, FitResult, Reference};
use crate::{fitting_source::SourceOutline, probe::FittedCommand, Error};

fn cap_height_violation(
    raw: &SourceOutline,
    upstream: &[FittedCommand],
    previous: &[FittedCommand],
) -> bool {
    let (Ok(up), Ok(prior)) = (
        geometry::parse_commands(upstream),
        geometry::parse_commands(previous),
    ) else {
        return false;
    };
    if raw.contours != up.contours
        || up.contours != prior.contours
        || raw.oncurve.len() != up.oncurve.len()
    {
        return false;
    }
    if raw
        .oncurve
        .iter()
        .chain(&raw.offcurve)
        .any(|p| !p[0].is_finite() || !p[1].is_finite())
    {
        return false;
    }
    // The dispatcher and solve share reference-edge eligibility. A local
    // cap below an ascender must trigger the same hard rows as a global cap.
    super::terminal::detect_caps(raw, &up).0.iter().any(|cap| {
        [cap.vertices.0, cap.vertices.1]
            .iter()
            .any(|&v| prior.oncurve[v][1] != up.oncurve[v][1])
    })
}

pub fn fit(
    raw: Option<&SourceOutline>,
    source: &[FittedCommand],
    upstream: &[FittedCommand],
    size_px: f64,
    reference: &Reference,
    native_axes: [bool; 2],
) -> Result<FitResult, Error> {
    // The reviewed sequence replaces earlier deliveries, using original
    // inputs for attached/crossing solves. Evaluate that priority lazily:
    // work whose entire result would be overwritten has no authority.
    let source_analysis = super::SourceAnalysis::new(source);
    let crossing = raw
        .and_then(|raw| {
            super::crossing::fit_for_selection(
                raw,
                source,
                upstream,
                size_px,
                reference,
                native_axes,
            )
            .ok()
        })
        .filter(|fit| fit.applied);
    let attached = || {
        super::attached::fit_with_analysis(
            source,
            upstream,
            size_px,
            reference,
            native_axes,
            &source_analysis,
        )
        .ok()
        .filter(|fit| fit.applied)
    };
    let (mut selected, mut stage) = if let Some(fit) = crossing {
        (fit, "crossing")
    } else if let Some(fit) = attached() {
        (fit, "attached")
    } else {
        let width = super::fit_with_analysis(
            source,
            upstream,
            size_px,
            reference,
            native_axes,
            &source_analysis,
        )?;
        let curve = super::curve_model::fit_horizontal(
            source,
            &width.commands,
            size_px,
            reference,
            native_axes,
        )
        .ok()
        .filter(|fit| fit.applied);
        if let Some(fit) = curve {
            (fit, "curve")
        } else if let Some(fit) =
            super::joint::fit_for_selection(source, upstream, size_px, reference, native_axes)
                .ok()
                .filter(|fit| fit.applied)
        {
            (fit, "joint")
        } else {
            (width, "width")
        }
    };
    if let Some(raw) = raw {
        if cap_height_violation(raw, upstream, &selected.commands) {
            let terminal = super::terminal::fit_terminal(
                raw,
                source,
                upstream,
                size_px,
                reference,
                native_axes,
            );
            if terminal.applied {
            failures.push("selective fitting does not reproduce from captured inputs");
        }
    }
    #[cfg(feature = "candidate")]
    if let Some(width) = &record.width_fitting {
        if record.selected_engine != "auto"
            || !matches!(
                record.raster_policy,
                RasterPolicy::FreeTypeMono | RasterPolicy::FreeTypeMonoTerminals
            )
        {
            failures.push("width fitting on an incompatible render policy");
        }
        let Some(source) = &record.source_commands else {
            failures.push("width source outline missing");
            return failures;
        };
        // Post-diagonal records reproduce the pre-diagonal outline.
        let expected: &[crate::probe::FittedCommand] = record
            .diagonal_fitting
            .as_ref()
            .map(|diagonal| diagonal.upstream_commands.as_slice())
            .unwrap_or(record.fitted_commands.as_slice());
        match crate::source_width::fit(source, &width.upstream_commands, width.size_px) {
            Ok(fit) if fit.applied && fit.commands == expected => {}
            _ => failures.push("width fitting does not reproduce from captured inputs"),
        }
    }
    reproduce_raster(record, &config, &mut failures);
    failures
}

