use super::{geometry, FitResult, Reference};
use crate::{fitting_source::SourceOutline, probe::FittedCommand, Error};

fn cap_height_violation(
    raw: &SourceOutline,
    upstream: &[FittedCommand],
    previous: &[FittedCommand],
) -> bool {
    let (Ok(up), Ok(prior)) = (
        geometry::parse_commands(upstream),
        geometry::parse_commands(previous),
    ) else {
        return false;
    };
    if raw.contours != up.contours
        || up.contours != prior.contours
        || raw.oncurve.len() != up.oncurve.len()
    {
        return false;
    }
    if raw
        .oncurve
        .iter()
        .chain(&raw.offcurve)
        .any(|p| !p[0].is_finite() || !p[1].is_finite())
    {
        return false;
    }
    // The dispatcher and solve share reference-edge eligibility. A local
    // cap below an ascender must trigger the same hard rows as a global cap.
    super::terminal::detect_caps(raw, &up).0.iter().any(|cap| {
        [cap.vertices.0, cap.vertices.1]
            .iter()
            .any(|&v| prior.oncurve[v][1] != up.oncurve[v][1])
    })
}

pub fn fit(
    raw: Option<&SourceOutline>,
    source: &[FittedCommand],
    upstream: &[FittedCommand],
    size_px: f64,
    reference: &Reference,
    native_axes: [bool; 2],
) -> Result<FitResult, Error> {
    // The reviewed sequence replaces earlier deliveries, using original
    // inputs for attached/crossing solves. Evaluate that priority lazily:
    // work whose entire result would be overwritten has no authority.
    let source_analysis = super::SourceAnalysis::new(source);
    let crossing = raw
        .and_then(|raw| {
            super::crossing::fit_for_selection(
                raw,
                source,
                upstream,
                size_px,
                reference,
                native_axes,
            )
            .ok()
        })
        .filter(|fit| fit.applied);
    let attached = || {
        super::attached::fit_with_analysis(
            source,
            upstream,
            size_px,
            reference,
            native_axes,
            &source_analysis,
        )
        .ok()
        .filter(|fit| fit.applied)
    };
    let (mut selected, mut stage) = if let Some(fit) = crossing {
        (fit, "crossing")
    } else if let Some(fit) = attached() {
        (fit, "attached")
    } else {
        let width = super::fit_with_analysis(
            source,
            upstream,
            size_px,
            reference,
            native_axes,
            &source_analysis,
        )?;
        let curve = super::curve_model::fit_horizontal(
            source,
            &width.commands,
            size_px,
            reference,
            native_axes,
        )
        .ok()
        .filter(|fit| fit.applied);
        if let Some(fit) = curve {
            (fit, "curve")
        } else if let Some(fit) =
            super::joint::fit_for_selection(source, upstream, size_px, reference, native_axes)
                .ok()
                .filter(|fit| fit.applied)
        {
            (fit, "joint")
        } else {
            (width, "width")
        }
    };
    if let Some(raw) = raw {
        if cap_height_violation(raw, upstream, &selected.commands) {
            let terminal = super::terminal::fit_terminal(
                raw,
                source,
                upstream,
                size_px,
                reference,
                native_axes,
            );
            if terminal.applied {
            failures.push("selective fitting does not reproduce from captured inputs");
        }
    }
    #[cfg(feature = "candidate")]
    if let Some(width) = &record.width_fitting {
        if record.selected_engine != "auto"
            || !matches!(
                record.raster_policy,
                RasterPolicy::FreeTypeMono | RasterPolicy::FreeTypeMonoTerminals
            )
        {
            failures.push("width fitting on an incompatible render policy");
        }
        let Some(source) = &record.source_commands else {
            failures.push("width source outline missing");
            return failures;
        };
        // Post-diagonal records reproduce the pre-diagonal outline.
        let expected: &[crate::probe::FittedCommand] = record
            .diagonal_fitting
            .as_ref()
            .map(|diagonal| diagonal.upstream_commands.as_slice())
            .unwrap_or(record.fitted_commands.as_slice());
        match crate::source_width::fit(source, &width.upstream_commands, width.size_px) {
            Ok(fit) if fit.applied && fit.commands == expected => {}
            _ => failures.push("width fitting does not reproduce from captured inputs"),
        }
    }
    reproduce_raster(record, &config, &mut failures);
    failures
}

