fn box_hit(
    w: &(BigRational, BigRational),
    u: &(BigRational, BigRational),
    v: &(BigRational, BigRational),
) -> bool {
    use std::cmp::{max, min};
    let (lox, hix) = (min(&u.0, &v.0), max(&u.0, &v.0));
    let (loy, hiy) = (min(&u.1, &v.1), max(&u.1, &v.1));
    lox <= &w.0 && &w.0 <= hix && loy <= &w.1 && &w.1 <= hiy
}

